#!/usr/bin/env python3
# MCP Gateway (Tool Federation and Governance): one governed entrypoint sits in
# front of several backend MCP servers. Every call is authenticated, resolved by
# namespace to a backend, checked against a per-caller allowlist, rate-limited,
# proxied with a scoped downstream credential the agent never sees, and audited.

from dataclasses import dataclass
from typing import Callable, Dict, List, Optional

@dataclass
class BackendServer:
    name: str
    tools: List[str]
    credential: str  # held by the gateway, never exposed to the caller
    handle: Callable[[str, Dict[str, str], str], str]

@dataclass
class Request:
    token: str
    tool: str  # namespaced: "server.tool"
    args: Dict[str, str]

class Gateway:
    def __init__(self) -> None:
        self.servers: Dict[str, BackendServer] = {}
        self.tokens: Dict[str, str] = {}
        self.allow: Dict[str, List[str]] = {}
        self.audit: List[str] = []
        self.used = 0
        self.quota = 60  # calls per minute

    def federate(self, server: BackendServer) -> None:
        self.servers[server.name] = server

    def grant(self, token: str, identity: str, tools: List[str]) -> None:
        self.tokens[token] = identity
        self.allow[identity] = tools

    def _record(self, caller: str, tool: str, backend: str, decision: str) -> None:
        self.audit.append(f"caller={caller:<13} tool={tool:<22} backend={backend:<9} decision={decision}")

    def _reply(self, text: str) -> str:
        print(f"Agent <- {text}\n")
        return text

    def call(self, req: Request) -> str:
        print(f'Agent -> gateway.call(token={req.token}, tool="{req.tool}")')
        identity: Optional[str] = self.tokens.get(req.token)
        if identity is None:
            print(f"  [authn] token {req.token} -> unknown -> DENY")
            self._record("unknown", req.tool, "-", "deny-authn")
            return self._reply("authentication failed")
        print(f"  [authn] token {req.token} -> identity {identity}")

        server_name, _, bare_tool = req.tool.partition(".")
        server = self.servers.get(server_name)
        if server is None:
            print(f"  [route] namespace '{server_name}' -> no such backend -> DENY")
            self._record(identity, req.tool, "-", "deny-route")
            return self._reply("unknown tool namespace")
        print(f"  [route] namespace '{server_name}' -> {server_name} MCP server")

        if req.tool not in self.allow.get(identity, []):
            print(f"  [authz] {identity} NOT allowed {req.tool} -> DENY (before backend)")
            self._record(identity, req.tool, server_name, "deny-authz")
            return self._reply(f"{req.tool} not in caller scope")
        print(f"  [authz] {identity} allowed {req.tool} -> ALLOW")

        self.used += 1
        if self.used > self.quota:
            print(f"  [policy] over {self.quota}/min quota -> DENY (rate limit)")
            self._record(identity, req.tool, server_name, "deny-quota")
            return self._reply("rate limit exceeded")
        print(f"  [policy] under {self.quota}/min quota (used {self.used}) -> OK")

        print(f"  [creds] swap in scoped credential {server.credential} (agent never sees it)")
        result = server.handle(bare_tool, req.args, server.credential)
        print(f"  [proxy] {req.tool} -> {result}")
        self._record(identity, req.tool, server_name, "allow")
        return self._reply(result)

    def dump_audit(self) -> None:
        print("Audit log (every call, one line):")
        for line in self.audit:
            print("  " + line)

def guarded_handler(expected: str, table: Dict[str, str]) -> Callable[[str, Dict[str, str], str], str]:
    def handler(tool: str, args: Dict[str, str], cred: str) -> str:
        if cred != expected:
            return "error: bad downstream credential"
        return table.get(tool, f"error: {tool} not implemented")
    return handler

def main() -> None:
    gw = Gateway()
    gw.federate(BackendServer("calendar", ["create_event"], "cred:calendar-svc",
                              guarded_handler("cred:calendar-svc", {"create_event": "event evt-5521 created for 2 attendees"})))
    gw.federate(BackendServer("crm", ["lookup_contact"], "cred:crm-svc",
                              guarded_handler("cred:crm-svc", {"lookup_contact": "contact CRM-77: Dana Ellis"})))
    gw.federate(BackendServer("docs", ["read_file"], "cred:docs-svc",
                              guarded_handler("cred:docs-svc", {"read_file": "read 3 KB from onboarding.md"})))
    gw.federate(BackendServer("billing", ["issue_refund"], "cred:billing-svc",
                              guarded_handler("cred:billing-svc", {"issue_refund": "refund issued 40.00"})))

    gw.grant("tok-abc", "assistant-bot", ["calendar.create_event", "crm.lookup_contact", "docs.read_file"])
    print("4 MCP servers federated behind one entrypoint: calendar, crm, docs, billing\n")

    requests = [
        Request("tok-abc", "calendar.create_event", {"title": "kickoff"}),
        Request("tok-abc", "billing.issue_refund", {"order": "4821"}),
        Request("tok-bad", "calendar.create_event", {"title": "sneaky"}),
        Request("tok-abc", "crm.lookup_contact", {"id": "77"}),
    ]
    for req in requests:
        gw.call(req)
    gw.dump_audit()

if __name__ == "__main__":
    main()

code.rust:
// MCP Gateway (Tool Federation and Governance): one governed entrypoint sits in
// front of several backend MCP servers. Every call is authenticated, resolved by
// namespace to a backend, checked against a per-caller allowlist, rate-limited,
// proxied with a scoped downstream credential the agent never sees, and audited.

use std::collections::HashMap;

struct BackendServer {
    tools: Vec<(String, String)>, // tool name -> canned result
    credential: String,           // held by the gateway, never exposed to the caller
}

impl BackendServer {
    fn handle(&self, tool: &str, cred: &str) -> String {
        if cred != self.credential {
            return "error: bad downstream credential".to_string();
        }
        for (name, result) in &self.tools {
            if name == tool {
                return result.clone();
            }
        }
        format!("error: {} not implemented", tool)
    }
}

struct Request {
    token: String,
    tool: String, // namespaced: "server.tool"
}

struct Gateway {
    servers: HashMap<String, BackendServer>,
    tokens: HashMap<String, String>,
    allow: HashMap<String, Vec<String>>,
    audit: Vec<String>,
    used: i32,
    quota: i32,
}

impl Gateway {
    fn new() -> Self {
        Gateway { servers: HashMap::new(), tokens: HashMap::new(), allow: HashMap::new(),
                  audit: Vec::new(), used: 0, quota: 60 }
    }

    fn federate(&mut self, name: &str, server: BackendServer) {
        self.servers.insert(name.to_string(), server);
    }

    fn grant(&mut self, token: &str, identity: &str, tools: Vec<String>) {
        self.tokens.insert(token.to_string(), identity.to_string());
        self.allow.insert(identity.to_string(), tools);
    }

    fn record(&mut self, caller: &str, tool: &str, backend: &str, decision: &str) {
        self.audit.push(format!("caller={:<13} tool={:<22} backend={:<9} decision={}", caller, tool, backend, decision));
    }

    fn reply(&self, text: &str) -> String {
        println!("Agent <- {}\n", text);
        text.to_string()
    }

    fn call(&mut self, req: &Request) -> String {
        println!("Agent -> gateway.call(token={}, tool=\"{}\")", req.token, req.tool);
        let identity = match self.tokens.get(&req.token) {
            Some(id) => id.clone(),
            None => {
                println!("  [authn] token {} -> unknown -> DENY", req.token);
                self.record("unknown", &req.tool, "-", "deny-authn");
                return self.reply("authentication failed");
            }
        };
        println!("  [authn] token {} -> identity {}", req.token, identity);

        let parts: Vec<&str> = req.tool.splitn(2, '.').collect();
        let server_name = parts[0].to_string();
        let bare_tool = if parts.len() > 1 { parts[1].to_string() } else { String::new() };
        if !self.servers.contains_key(&server_name) {
            println!("  [route] namespace '{}' -> no such backend -> DENY", server_name);
            self.record(&identity, &req.tool, "-", "deny-route");
            return self.reply("unknown tool namespace");
        }
        println!("  [route] namespace '{}' -> {} MCP server", server_name, server_name);

        let allowed = self.allow.get(&identity).cloned().unwrap_or_default();
        if !allowed.contains(&req.tool) {
            println!("  [authz] {} NOT allowed {} -> DENY (before backend)", identity, req.tool);
            self.record(&identity, &req.tool, &server_name, "deny-authz");
            return self.reply(&format!("{} not in caller scope", req.tool));
        }
        println!("  [authz] {} allowed {} -> ALLOW", identity, req.tool);

        self.used += 1;
        if self.used > self.quota {
            println!("  [policy] over {}/min quota -> DENY (rate limit)", self.quota);
            self.record(&identity, &req.tool, &server_name, "deny-quota");
            return self.reply("rate limit exceeded");
        }
        println!("  [policy] under {}/min quota (used {}) -> OK", self.quota, self.used);

        let server = self.servers.get(&server_name).unwrap();
        println!("  [creds] swap in scoped credential {} (agent never sees it)", server.credential);
        let result = server.handle(&bare_tool, &server.credential);
        println!("  [proxy] {} -> {}", req.tool, result);
        self.record(&identity, &req.tool, &server_name, "allow");
        self.reply(&result)
    }

    fn dump_audit(&self) {
        println!("Audit log (every call, one line):");
        for line in &self.audit {
            println!("  {}", line);
        }
    }
}

fn server(cred: &str, tools: Vec<(&str, &str)>) -> BackendServer {
    BackendServer {
        credential: cred.to_string(),
        tools: tools.iter().map(|(n, r)| (n.to_string(), r.to_string())).collect(),
    }
}

fn main() {
    let mut gw = Gateway::new();
    gw.federate("calendar", server("cred:calendar-svc", vec![("create_event", "event evt-5521 created for 2 attendees")]));
    gw.federate("crm", server("cred:crm-svc", vec![("lookup_contact", "contact CRM-77: Dana Ellis")]));
    gw.federate("docs", server("cred:docs-svc", vec![("read_file", "read 3 KB from onboarding.md")]));
    gw.federate("billing", server("cred:billing-svc", vec![("issue_refund", "refund issued 40.00")]));

    gw.grant("tok-abc", "assistant-bot",
             vec!["calendar.create_event".to_string(), "crm.lookup_contact".to_string(), "docs.read_file".to_string()]);
    println!("4 MCP servers federated behind one entrypoint: calendar, crm, docs, billing\n");

    let requests = vec![
        Request { token: "tok-abc".to_string(), tool: "calendar.create_event".to_string() },
        Request { token: "tok-abc".to_string(), tool: "billing.issue_refund".to_string() },
        Request { token: "tok-bad".to_string(), tool: "calendar.create_event".to_string() },
        Request { token: "tok-abc".to_string(), tool: "crm.lookup_contact".to_string() },
    ];
    for req in &requests {
        gw.call(req);
    }
    gw.dump_audit();
}

